 if(element!=null&&Convert.ToString(element.Tag)=="RecentLayer:"+recentEditorSection){
 var point=element.TranslatePoint(new Point(),root);var handle=new Thumb{Width=Math.Max(12,(element.ActualWidth>0?element.ActualWidth:(!Double.IsNaN(element.Width)?element.Width:80))*scale),Height=Math.Max(12,(element.ActualHeight>0?element.ActualHeight:(!Double.IsNaN(element.Height)?element.Height:24))*scale),Background=new SolidColorBrush(Color.FromArgb(30,91,154,160)),BorderBrush=accentBrush,BorderThickness=new Thickness(1),Cursor=Cursors.SizeAll};double px=left+point.X*scale,py=top+point.Y*scale;Canvas.SetLeft(handle,px);Canvas.SetTop(handle,py);StyleRecentThumb(handle);recentStage.Children.Add(handle);string layer=recentEditorSection;double dx=0,dy=0;double lw=Math.Max(12,element.ActualWidth),lh=Math.Max(12,element.ActualHeight);WidgetResizeHandle(recentStage,px+handle.Width-8,py+handle.Height-8,()=>false,(rx,ry)=>{lw=Clamp(lw+rx/scale,12,2000);lh=Clamp(lh+ry/scale,12,2000);var origin=element.TranslatePoint(new Point(),root);element.Width=lw;element.Height=lh;element.UpdateLayout();var shifted=element.TranslatePoint(new Point(),root);var transform=element.RenderTransform as TranslateTransform??new TranslateTransform();element.RenderTransform=new TranslateTransform(transform.X+origin.X-shifted.X,transform.Y+origin.Y-shifted.Y);handle.Width=lw*scale;handle.Height=lh*scale;},()=>{var finalTransform=element.RenderTransform as TranslateTransform;if(finalTransform!=null){SetRecentOffset(layer,"X",finalTransform.X);SetRecentOffset(layer,"Y",finalTransform.Y);}RecentStyle(layer).Width=lw;RecentStyle(layer).Height=lh;ChangeRecents();RefreshRecentsEditor();});
 handle.DragDelta+=delegate(object sender,DragDeltaEventArgs e){dx+=e.HorizontalChange;dy+=e.VerticalChange;Canvas.SetLeft(handle,px+dx);Canvas.SetTop(handle,py+dy);MoveRecentLayerLive(root,layer,RecentOffset(layer,"X")+dx/scale,RecentOffset(layer,"Y")+dy/scale);};handle.DragCompleted+=delegate{SetRecentOffset(layer,"X",RecentOffset(layer,"X")+dx/scale);SetRecentOffset(layer,"Y",RecentOffset(layer,"Y")+dy/scale);ChangeRecents();RefreshRecentsEditor();};
 }
 for(int i=0;i<VisualTreeHelper.GetChildrenCount(node);i++)AddRecentLayerHandles(VisualTreeHelper.GetChild(node,i),root,scale,left,top);
